Kvadratna jednačina ima bar jedno realno rešenje ako i samo ako je njena diskriminanta nenegativna, tj.\ u situaciji iz zadatka ako i samo ako je $D(n) = (b+2n)^2 - 4(a+n)(b+n) = 4(b-a-c)n + b^2 - 4ac \geqslant 0$.
    \begin{itemize}
        \item[$1^\circ$] Ako je $b - a - c < 0$ i $n \in \mathbb{N}$, $n > \frac{4ac-b^2}{4(b-a-c)}$ (postoji ovakav prirodan broj), sledi $D(n) = 4(b-a-c)n + b^2 - 4ac < 4(b-a-c) \cdot \frac{4ac-b^2}{4(b-a-c)} + b^2 - 4ac = 0$, pa $D(n) \geqslant 0$ ne može da važi za svako $n \in \mathbb{N}$.
        \item[$2^\circ$] Ako je $b-a-c = 0$, važi $D(n) = b^2 - 4ac = (a+c)^2 - 4ac = (a-c)^2 \geqslant 0$.
        \item[$3^\circ$] Ako je $b - a - c > 0$, važi $b > a + c > 0$ (i $n > 0$), pa je $D(n) = 4(b-a-c)n + b^2 - 4ac > 0 + (a+c)^2 - 4ac = (a-c)^2 \geqslant 0$.
    \end{itemize}
