    \[
        \begin{array}{rcl}
            \displaystyle\sum_{b=2}^{2010} \frac{b(b-1)}{2} &=& \dfrac{1}{2} \cdot \left(\displaystyle\sum_{b=1}^{2010} b^2 - \sum_{b=1}^{2010} b\right)\\[6mm]
            &=& \dfrac{1}{2} \cdot \left(\dfrac{2010 \cdot 2011 \cdot 4021}{6} - \dfrac{2010 \cdot 2011}{2}\right) = \dbinom{2011}{3}.
        \end{array}
    \]

